select * from jsonb_populate_recordset(null::public.temples, $rtam$[{"id":"ed7c3c01-f030-44cb-a196-6b5518b865b7","name":"Naba Kailash Mandir (108 Shiva Temples), Kalna","deity":"Shiva — 108 individual lingas, one per shrine; inner-circle lingas are white (Sadashiva), outer-circle lingas alternate black and white (Rudra)","sampradaya":"Shaiva","significance":["108 Shiva shrines"],"country":"India","state":"West Bengal","district":"Purba Bardhaman","town":"Kalna","latitude":23.22028,"longitude":88.36472,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Bhagirathi (Hooghly)","river_distance_km":0.3,"best_season_notes":"Maha Shivaratri is the major festival.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-22T09:14:22.726852+00:00","updated_at":"2026-09-22T09:14:22.726852+00:00","sthala_purana":"Built by Maharaja Teja Chandra Bahadur of the Burdwan Raj, completed in 1809 — well-documented, not legendary.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Netaji Subhas Chandra Bose International Airport, Kolkata","nearest_airport_distance_km":85,"nearest_railway_station_name":"Ambika Kalna railway station","nearest_railway_distance_km":1,"emergency_contact_notes":null,"sthala_purana_source":"Burdwan Raj institutional records","architecture_style":"Two concentric circles of small at-chala/chala-style shrines — 74 in the outer circle, 34 in the inner — plus one pancha-ratna shrine (Jaleswar Mandir) on the west side of the outer circle. Inner circle roughly 102m in circumference, outer roughly 220m; standard shrines about 20ft tall, the Jaleswar Mandir about 35ft; laid out so all 108 lingas are visible from the centre.","construction_century":19},{"id":"ed8309c9-24e2-40a1-8985-1ff2a9b4f6d6","name":"Mallikarjuna Jyotirlinga, Srisailam","deity":"Shiva (Mallikarjuna)","sampradaya":null,"significance":["Jyotirlinga","Shakti Peetha","Trilinga Kshetra"],"country":"India","state":"Andhra Pradesh","district":"Nandyal","town":"Srisailam","latitude":16.074,"longitude":78.8677,"sandhya_friendly":"yes","sandhya_notes":"The temple overlooks the Krishna river gorge; ghats below the town give river access.","samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"pure_veg_available","food_source_name":"Sri Bhramaramba Mallikarjuna Devasthanam Annadanam Hall — free meals twice daily, serving thousands","food_source_contact":null,"food_distance_km":0.3,"nearest_river_name":"Krishna","river_distance_km":1,"best_season_notes":"Nov–Feb; the ghat road up the forest reserve floods and can wash out in the June–September monsoon, and the Andhra coast's cyclone season (Oct–Nov) is worth watching before booking.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T11:51:56.898831+00:00","updated_at":"2026-11-04T12:15:00.624755+00:00","sthala_purana":"Shiva and Parvati are said to have come to this hill in search of their son Kartikeya, who had withdrawn here in anger after the contest over the divine fruit. They took the forms of Mallikarjuna and Bhramaramba to remain near him. The site is both a Jyotirlinga and a Shakti Peetha.","etiquette_notes":null,"native_name":"మల్లికార్జున జ్యోతిర్లింగం","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Uyyalawada Narasimha Reddy Airport ,   Kurnool","nearest_airport_distance_km":84.7,"nearest_railway_station_name":"Tarlupadu railway station","nearest_railway_distance_km":59.1,"emergency_contact_notes":null,"sthala_purana_source":"Shiva Purana / Skanda Purana (Jyotirlinga tradition)","architecture_style":null,"construction_century":null},{"id":"eda39c0e-c821-46e3-b843-792062cf6fe5","name":"Rani Sati Temple","deity":"Rani Sati (Narayani Devi)","sampradaya":"Shakta","significance":[],"country":"India","state":"Rajasthan","district":"Jhunjhunu","town":"Jhunjhunu","latitude":28.13528,"longitude":75.40361,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Kantii River","river_distance_km":13.8,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:36.374917+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Located in Jhunjhunu, Rajasthan, this is described as the largest temple in India devoted to Rani Sati, also called Narayani Devi or Dadiji. She was a Rajasthani woman said to have lived between the 13th and 17th centuries and to have died by sati on her husband's death. Other temples to her exist elsewhere.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Hisar Airport","nearest_airport_distance_km":121.1,"nearest_railway_station_name":"Jhunjhunun railway station","nearest_railway_distance_km":3.4,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Rani Sati Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"edbda2d3-c612-4fd2-b55a-bc011ffc5870","name":"Sankata Devi Mandir","deity":"Sankata Devi","sampradaya":"Shakta","significance":[],"country":"India","state":"Uttar Pradesh","district":"Varanasi","town":"Varanasi","latitude":25.31269,"longitude":83.01528,"sandhya_friendly":"unknown","sandhy