ded later and it sees informal worship.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Warangal Airport","nearest_airport_distance_km":51,"nearest_railway_station_name":"Yelgur railway station","nearest_railway_distance_km":41.7,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Devunigutta Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":6},{"id":"ee44d757-56f9-4439-ae6f-594d948f442a","name":"Haleshwar Sthan","deity":"Shiva as Haleshwarnath","sampradaya":"Shaiva","significance":[],"country":"India","state":"Bihar","district":"Sitamarhi","town":"Sitamarhi","latitude":26.63388,"longitude":85.48489,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Jhim Nadi River","river_distance_km":10.8,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:59.639499+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A Shiva pilgrimage site about 7 km north-west of Sitamarhi. By local belief, King Janaka of Mithila installed a shivling here at the start of the Haleshti Yagna. A temple was built around the lingam in the 17th century and named Haleshwarnath. A bus service links it with Punaura Dham and a temple in Nepal.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Muzzafarpur Airport","nearest_airport_distance_km":59.8,"nearest_railway_station_name":"Sitamarhi railway station","nearest_railway_distance_km":4.8,"eme