":null,"sthala_purana_source":"Wikipedia (Swaminarayan Mandir, Vadtal), summarised; location via OpenStreetMap","architecture_style":"Wood-carved","construction_century":null},{"id":"f59f3e37-9cc7-42a1-8fe8-af984c00ef0b","name":"Nagareshvara Temple, Bankapura","deity":"Shiva as Nagareshvara","sampradaya":"Shaiva","significance":[],"country":"India","state":"Karnataka","district":"Haveri","town":"Munavalli","latitude":14.92586,"longitude":75.2497,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Varada River","river_distance_km":10,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:38.937899+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A 12th-century Western Chalukya temple inside the Bankapura fort, also called the temple with sixty-six columns. Inscriptions dated 1091 and 1138 CE record grants to Nagaresvaradeva. It was damaged in later sultanate-era attacks but keeps its great mantapa, and the Archaeological Survey of India protects it.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Hubballi Airport","nearest_airport_distance_km":51.7,"nearest_railway_station_name":"Kalsur railway station","nearest_railway_distance_km":16.8,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Nagareshvara Temple, Bankapura), summarised; location via OpenStreetMap","architecture_style":"Western Chalukya","construction_century":12},{"id":"f5d52dfd-cbc3-4835-a450-19163aea552f","name":"Chittoor Sree Krishnaswamy Temple","deity":"Krishna","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Kerala","district":"Ernakulam","town":"Cheranallur","latitude":10.0333,"longitude":76.2733,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Periyar River","river_distance_km":0.5,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:38.937899+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A Cochin Devaswom Board temple in Kochi, once tied to the Kartha family and later to the Cochin royal house. The four-armed standing Krishna faces east, much like the Guruvayoor image. Smaller shrines for Shiva, Ganesha, Ayyappan and others stand within the complex, along with a Kaliya statue and the Agnihotratheertham pond.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Cochin International Airport","nearest_airport_distance_km":19.5,"nearest_railway_station_name":"Idappalli railway station","nearest_railway_distance_km":2.8,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Chittoor Sree Krishnaswamy Temple), summarised; location via OpenStreetMap","architecture_style":"Kerala style","construction_century":null},{"id":"f5f6f9dd-4fdc-4f4a-8d68-a5ce08b251ea","name":"Badri Narayanan temple","deity":"Vishnu as Badri Narayana","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Tamil Nadu","district":"Madurai","town":"Valayapatti","latitude":10.06196,"longitude":78.21191,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Uppaar River","river_