nd 4 pm to 8 pm.","accessibility_notes":null,"nearest_airport_name":"Chennai International Airport","nearest_airport_distance_km":23.9,"nearest_railway_station_name":"Tiruvallur railway station","nearest_railway_distance_km":16.9,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Adikesava Perumal temple, Sriperumpudur), summarised; location via OpenStreetMap","architecture_style":"Dravidian","construction_century":null},{"id":"fc41ac85-df34-45f8-ad52-736f81f6fd10","name":"Trimbakeshwar Jyotirlinga","deity":"Shiva (Trimbakeshwar)","sampradaya":null,"significance":["Jyotirlinga"],"country":"India","state":"Maharashtra","district":"Nashik","town":"Trimbak","latitude":19.9328,"longitude":73.5306,"sandhya_friendly":"yes","sandhya_notes":"Kushavarta Kund, the traditional source-pool of the Godavari, is right by the temple.","samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Godavari (origin)","river_distance_km":0.1,"best_season_notes":"Oct–Feb; very crowded during Nashik-Trimbak Kumbh Mela (every 12 years).","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T11:51:56.898831+00:00","updated_at":"2026-09-04T08:49:12.455773+00:00","sthala_purana":"The Godavari rises at Brahmagiri above this temple, brought down by the penance of the sage Gautama to absolve him of the death of a cow. The lingam here has three faces — Brahma, Vishnu and Shiva — from which the name Trimbaka comes.","etiquette_notes":null,"native_name":"त्र्यंबकेश्वर ज्योतिर्लिंग","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Nashik Airport","nearest_airport_distance_km":30,"nearest_railway_station_name":"Nashik Road Railway Station","nearest_railway_distance_km":28,"emergency_contact_notes":